 "content": "def transform(grid):
    """Recolor every uniform row and every uniform column to color 2."""
    h = len(grid)
    if h == 0:
        return []
    w = len(grid[0])
    if any(len(row) != w for row in grid):
        raise ValueError("grid must be rectangular")
    out = [row[:] for row in grid]
    uniform_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    uniform_cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))]
    for r in uniform_rows:
        for c in range(w):
            out[r][c] = 2
    for c in uniform_cols:
        for r in range(h):
            out[r][c] = 2
    return out
